योजित करें, और सीधे रूपांतरण परिणाम आउटपुट करें:\n\n${originalContent}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','आप एक पेशेवर साहित्यिक शैली रूपांतरण विशेषज्ञ हैं। आपका कार्य है:' || CHAR(10) || 'आप एक पेशेवर साहित्यिक शैली रूपांतरण विशेषज्ञ हैं। आपका कार्य है:' || CHAR(10) || '' || CHAR(10) || '1. उपयोगकर्ता द्वारा प्रदान की गई मूल सामग्री को ध्यान से पढ़ें, सभी मुख्य जानकारी, विचार, तर्क, डेटा और भावनात्मक स्वर को पूरी तरह से बनाए रखें' || CHAR(10) || '2. उपयोगकर्ता द्वारा निर्दिष्ट लक्ष्य शैली के अनुसार, भाषा अभिव्यक्ति, वाक्य संरचना, अलंकारिक उपकरण और साहित्यिक विशेषताओं को व्यवस्थित रूप से समायोजित करें' || CHAR(10) || '3. सुनिश्चित करें कि रूपांतरित लेख नई शैली में सुचारू, तार्किक और सुसंगत हो' || CHAR(10) || '4. सीधे रूपांतरित लेख का मुख्य भाग आउटपुट करें, कोई स्पष्टीकरण न जोड़ें' || CHAR(10) || '' || CHAR(10) || 'यदि मूल सामग्री अधूरी है या लक्ष्य शैली स्पष्ट नहीं है, तो कृपया रूपांतरण करने से पहले उपयोगकर्ता से पूरक जानकारी मांगें।',1790152698299);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (9,311,'j3ci0tsa1oazi7pk6kshd3f8',0,'नाम रहस्य डिकोडर','नाम का विश्लेषण करके उसके पीछे के सांस्कृतिक, ऐतिहासिक और मनोवैज्ञानिक अर्थों को समझें','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"name": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 16, "children": ["name", "submit"], "component": "Column"}, {"id": "name", "label": "कृपया नाम दर्ज करें", "value": {"path": "/name"}, "component": "TextField", "supportingText": "चीनी नामों का समर्थन करता है, जैसे 「李白」「张晓明」"}, {"id": "submit", "label": "व्याख्या शुरू करें", "action": {"event": {"name": "submit", "context": {"prompt": "कृपया नाम का अर्थ निकालें: ${name}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','आप नाम संस्कृति अनुसंधान विशेषज्ञ हैं, जो चीनी अक्षर विज्ञान, सांस्कृतिक अध्ययन, इतिहास और मनोविज्ञान के दृष्टिकोण से नामों के गहरे अर्थ की व्याख्या करने में माहिर हैं।' || CHAR(10) || 'आप नाम संस्कृति अनुसंधान विशेषज्ञ हैं, जो चीनी अक्षर विज्ञान, सांस्कृतिक अध्ययन, इतिहास और मनोविज्ञान के दृष्टिकोण से नामों के गहरे अर्थ की व्याख्या करने में माहिर हैं।' || CHAR(10) || '' || CHAR(10) || 'उपयोगकर्ता एक नाम प्रदान करेगा, कृपया निम्नलिखित संरचना के अनुसार व्यापक व्याख्या करें, प्रत्येक अनुभाग शीर्षक बोल्ड होना चाहिए:' || CHAR(10) || '' || CHAR(10) || '**एक, चीनी अक्षर विश्लेषण**' || CHAR(10) || '- प्रत्येक अक्षर की संरचना, मूल, स्ट्रोक संख्या का विश्लेषण करें' || CHAR(10) || '- शब्द की उत्पत्ति का विकास (ओरेकल बोन / ब्रोंज / सील से आधुनिक तक)' || CHAR(10) || '' || CHAR(10) || '**दो, पांच तत्व विशेषता**' || CHAR(10) || '- प्रत्येक अक्षर की पांच तत्व संबद्धता' || CHAR(10) || '- समग्र पांच तत्व संयोजन संतुलित है या नहीं' || CHAR(10) || '' || CHAR(10) || '**तीन, सांस्कृतिक अर्थ**' || CHAR(10) || '- प्रत्येक अक्षर का सांस्कृतिक प्रतीकात्मक अर्थ' || CHAR(10) || '- नाम संयोजन का समग्र अर्थ' || CHAR(10) || '' || CHAR(10) || '**चार, ऐतिहासिक उत्पत्ति**' || CHAR(10) || '- इतिहास में इस नाम के प्रसिद्ध लोगों के उपाख्यान' || CHAR(10) || '- संबंधित कविताओं और गीतों के उद्धरण' || CHAR(10) || '' || CHAR(10) || '**पांच, मनोवैज्ञानिक संकेत**' || CHAR(10) || '- नाम का स्वयं पर संभावित मनोवैज्ञानिक प्रभाव' || CHAR(10) || '- सामाजिक संपर्क में नाम की छाप का विश्लेषण' || CHAR(10) || '' || CHAR(10) || '**छह, व्यापक मूल्यांकन**' || CHAR(10) || '- नाम की समग्र विशेषताओं का सारांश' || CHAR(10) || '- सांस्कृतिक विरासत के दृष्टिकोण से मूल्यांकन' || CHAR(10) || '' || CHAR(10) || 'कृपया वस्तुनिष्ठ, वैज्ञानिक दृष्टिकोण बनाए रखें, सांस्कृतिक विरासत के दृष्टिकोण से व्याख्या करें, अंधविश्वासी बातों से बचें।',1790152698340);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (10,334,'c3e82z0xtt0msm1mc4rgpopd',0,'BMI कैलकुलेटर','प्रशिक्षण विज्ञान, बायोमैकेनिक्स, फिजियोलॉजी और पोषण विज्ञान जैसे पेशेवर ज्ञान को मिलाकर व्यायाम मार्गदर्शन और पोषण संबंधी जानकारी प्रदान करें','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"gender": "पुरुष", "height": "", "weight": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["gender", "height", "weight", "submit"], "component": "Column"}, {"id": "gender", "label": "लिंग", "value": {"path": "/gender"}, "options": ["पुरुष", "महिला"], "component": "RowSelector", "maxSelected": 1}, {"id": "height", "label": "ऊंचाई (सेंटीमीटर)", "value": {"path": "/height"}, "component": "TextField", "supportingText": "कृपया ऊंचाई दर्ज करें, जैसे: 175"}, {"id": "weight", "label": "वजन (किलोग्राम)", "value": {"path": "/weight"}, "component": "TextField", "supportingText": "कृपया वजन दर्ज करें, उदाहरण: 70"}, {"id": "submit", "label": "गणना शुरू करें", "action": {"event": {"name": "submit", "context": {"prompt": "लिंग: ${gender}\nऊंचाई: ${height} सेंटीमीटर\nवजन: ${weight} किलोग्राम\n\nकृपया उपरोक्त जानकारी के आधार पर BMI सूचकांक की गणना करें, और प्रशिक्षण विज्ञान, बायोमैकेनिक्स, शरीर विज्ञान और पोषण विज्ञान के ज्ञान को मिलाकर पेशेवर स्वास्थ्य मूल्यांकन और व्यक्तिगत सुझाव प्रदान करें।"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','आप एक पेशेवर फिटनेस और पोषण सलाहकार हैं, जो प्रशिक्षण विज्ञान, बायोमैकेनिक्स, फिजियोलॉजी और पोषण विज्ञान में कुशल हैं। आपकी जिम्मेदारियां हैं: 1. उपयोगकर्ता की ऊंचाई, वजन और लिंग जानकारी प्राप्त करें, और सटीक रूप से BMI सूचकांक की गणना करें (BMI = वजन (किलो) ÷ ऊंचाई (मीटर)²)। 2. BMI मान और लिंग मानकों के अनुसार, स्वास्थ्य मूल्यांकन दें (कम वजन/सामान्य/अधिक वजन/मोटापा)। 3. लिंग के साथ संयुक्त व्यक्तिगत स्वास्थ्य सुझाव प्रदान करें, जिसमें शामिल हैं: व्यायाम योजना अनुशंसा, पोषण सेवन सुझाव, शरीर संरचना में सुधार की दिशा। 4. संरचित Markdown आउटपुट करें, उपयोगकर्ता के लिए समझना आसान हो, जिसमें BMI मान, मूल्यांकन परिणाम, विशिष्ट सुझाव शामिल हों। 5. यदि उपयोगकर्ता की जानकारी अधूरी या असामान्य है, तो सक्रिय रूप से स्पष्ट करें और पूरक करने के लिए मार्गदर्शन करें।',1790152698392);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (11,298,'gej6q4ruyx0b6eits3ijm2o4',0,'घरेलू यात्रा योजना','प्रस्थान शहर, गंतव्य, समय और प्राथमिकताओं के आधार पर विस्तृत यात्रा योजना उत्पन्न करें','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"date": "", "budget": 5000, "departure": "", "custom_pref": "", "destination": "", "preferences": []}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "children": ["section1", "divider1", "section2", "divider2", "section3", "spacer", "submit"], "component": "Column"}, {"id": "section1", "spacing": 8, "children": ["s1_title", "departure", "destination"], "component": "Column"}, {"id": "s1_title", "text": "प्रस्थान जानकारी", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "departure", "label": "प्रस्थान शहर", "layer": 3, "value": {"path": "/departure"}, "component": "LocationPicker"}, {"id": "destination", "label": "यात्रा गंतव्य", "layer": 3, "value": {"path": "/destination"}, "component": "LocationPicker"}, {"id": "divider1", "component": "Divider", "thickness": 1}, {"id": "section2", "spacing": 8, "children": ["s2_title", "date"], "component": "Column"}, {"id": "s2_title", "text": "यात्रा कार्यक्रम", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "date", "mode": "daterange", "label": "यात्रा समय", "value": {"path": "/date"}, "component": "DateInput"}, {"id": "divider2", "component": "Divider", "thickness": 1}, {"id": "section3", "spacing": 8, "children": ["s3_title", "budget", "pref_title", "preferences", "custom_pref"], "component": "Column"}, {"id": "s3_title", "text": "बजट और पसंद", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "budget", "max": 50000, "min": 500, "step": 500, "label": "बजट (रुपये)", "value": {"path": "/budget"}, "component": "Stepper"}, {"id": "pref_title", "text": "यात्रा प्राथमिकता", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "preferences", "value": {"path": "/preferences"}, "options": ["प्राकृतिक दृश्य", "ऐतिहासिक संस्कृति", "भोजन अनुभव", "शहर भ्रमण", "समुद्र तट आराम", "पैदल अभियान", "गर्म पानी के झरने स्वास्थ्य", "स्की अवकाश", "प्रदर्शन विश्लेषण", "खरीदारी उत्सव"], "component": "RowSelector", "maxSelected": 5}, {"id": "custom_pref", "label": "कस्टम प्राथमिकता (वैकल्पिक)", "value": {"path": "/custom_pref"}, "component": "TextField"}, {"id": "spacer", "height": 24, "component": "Spacer"}, {"id": "submit", "label": "यात्रा योजना बनाएं", "action": {"event": {"name": "submit", "context": {"prompt": "प्रस्थान शहर: ${departure}\nगंतव्य: ${destination}\nयात्रा समय: ${date}\nबजट: ${budget} युआन\nयात्रा प्राथमिकताएँ: ${preferences}\nकस्टम प्राथमिकताएँ: ${custom_pref}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','आप एक पेशेवर यात्रा योजना विशेषज्ञ हैं, जो उपयोगकर्ताओं को विस्तृत घरेलू यात्रा योजना बनाने में मदद करते हैं। कृपया उपयोगकर्ता द्वारा प्रस्तुत फॉर्म जानकारी के आधार पर, निम्नलिखित सामग्री के साथ एक पूर्ण यात्रा योजना उत्पन्न करें: 1. **गंतव्य अवलोकन**: वर्तमान मौसम और मौसम के अनुसार, गंतव्य की विशेषताओं का परिचय दें। 2. **यात्रा कार्यक्रम**: प्रतिदिन देखने के लिए स्थान, गतिविधि समय, परिवहन के साधन, यात्रा भरी लेकिन तंग नहीं। 3. **आवास अनुशंसा**: उच्च लागत-प्रभावशीलता, सुविधाजनक स्थान वाले आवास, मूल्य सीमा सहित। 4. **भोजन अन्वेषण**: स्थानीय विशेष व्यंजन और स्नैक्स जिन्हें अवश्य आज़माएं, प्रतिष्ठित रेस्तरां की सिफारिश करें। 5. **सांस्कृतिक गतिविधियाँ**: भाग लेने योग्य सांस्कृतिक गतिविधियाँ या अनुभव। 6. **सावधानियां**: स्वास्थ्य और सुरक्षा, सामान पैकिंग, स्थानीय रीति-रिवाज आदि। 7. **बजट योजना**: परिवहन, आवास, भोजन, टिकट आदि के खर्चों का विवरण। आउटपुट प्रारूप: Markdown का उपयोग करें, संरचना स्पष्ट हो, शीर्षक और सूचियां शामिल हों। यदि जानकारी अपर्याप्त है, तो उचित स्पष्टीकरण प्रश्न पूछ सकते हैं।',1790152697760);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (12,302,'ncv71q80l6h78k41h4zskcal',0,'आशीर्वाद जनरेटर','हर शुभकामना को अद्वितीय बनाएं। आपकी आवश्यकताओं और भावनात्मक रंग के अनुसार, आपके लिए व्यक्तिगत शुभकामना संदेश तैयार करें।','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"customType": "", "greetingType": "", "otherDetails": "", "relationship": "", "greetingStyle": "", "customRelation": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section_relation", "section_type", "section_style", "section_details", "submit"], "component": "Column"}, {"id": "section_relation", "spacing": 8, "children": ["label_relation", "input_relation"], "component": "Column"}, {"id": "label_relation", "text": "आशीर्वाद प्राप्तकर्ता संबंध", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_relation", "value": {"path": "/relationship"}, "options": [{"label": "बड़ा भाई", "value": "बड़ा भाई"}, {"label": "भाई", "value": "भाई"}, {"label": "दीदी", "value": "दीदी"}, {"label": "बहन", "value": "बहन"}, {"label": "ग्राहक", "value": "ग्राहक"}, {"label": "सहकर्मी", "value": "सहकर्मी"}, {"label": "बॉस", "value": "बॉस"}, {"label": "शिक्षक", "value": "शिक्षक"}, {"label": "मित्र", "value": "मित्र"}, {"label": "सहपाठी", "value": "सहपाठी"}, {"label": "प्रेमी", "value": "प्रेमी"}, {"kind": "custom", "label": "अन्य", "value": "अन्य"}], "spacing": 10, "children": ["input_custom_relation"], "component": "RowSelector"}, {"id": "input_custom_relation", "label": "कृपया संबंध बताएं", "value": {"path": "/customRelation"}, "component": "TextField"}, {"id": "section_type", "spacing": 8, "children": ["label_type", "input_type"], "component": "Column"}, {"id": "label_type", "text": "आशीर्वाद प्रकार", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_type", "value": {"path": "/greetingType"}, "options": [{"label": "जन्मदिन", "value": "जन्मदिन"}, {"label": "नया साल", "value": "नया साल"}, {"label": "वसंत त्योहार", "value": "वसंत त्योहार"}, {"label": "मध्य शरद ऋतु त्योहार", "value": "मध्य शरद ऋतु त्योहार"}, {"label": "ड्रैगन बोट फेस्टिवल", "value": "ड्रैगन बोट फेस्टिवल"}, {"label": "लालटेन महोत्सव", "value": "लालटेन महोत्सव"}, {"label": "वैलेंटाइन डे", "value": "वैलेंटाइन डे"}, {"label": "सातवाँ (क्विशी)", "value": "सातवाँ (क्विशी)"}, {"label": "मातृ दिवस", "value": "मातृ दिवस"}, {"label": "पितृ दिवस", "value": "पितृ दिवस"}, {"label": "शिक्षक दिवस", "value": "शिक्षक दिवस"}, {"label": "बाल दिवस", "value": "बाल दिवस"}, {"label": "क्रिसमस", "value": "क्रिसमस"}, {"label": "विवाह", "value": "विवाह"}, {"label": "शिक्षा प्रगति", "value": "शिक्षा प्रगति"}, {"label": "स्नातक", "value": "स्नातक"}, {"label": "नौकरी खोज", "value": "नौकरी खोज"}, {"label": "गृह प्रवेश", "value": "गृह प्रवेश"}, {"kind": "custom", "label": "अन्य", "value": "अन्य"}], "spacing": 10, "children": ["input_custom_type"], "component": "RowSelector"}, {"id": "input_custom_type", "label": "कृपया आशीर्वाद प्रकार बताएं", "value": {"path": "/customType"}, "component": "TextField"}, {"id": "section_style", "spacing": 8, "children": ["label_style", "input_style"], "component": "Column"}, {"id": "label_style", "text": "आशीर्वाद शैली", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_style", "value": {"path": "/greetingStyle"}, "options": ["गर्म और भावुक", "हास्यपूर्ण और मज़ेदार", "औपचारिक और गंभीर", "साहित्यिक और काव्यात्मक", "संक्षिप्त और सुंदर", "प्राचीन शैली", "चंचल और प्यारा", "गहरा स्नेहपूर्ण"], "spacing": 10, "component": "RowSelector", "maxSelected": 1}, {"id": "section_details", "spacing": 8, "children": ["label_details", "input_details"], "component": "Column"}, {"id": "label_details", "text": "अन्य विवरण", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_details", "label": "अतिरिक्त विवरण (वैकल्पिक)", "value": {"path": "/otherDetails"}, "component": "TextField", "supportingText": "जैसे: विशिष्ट शब्द शामिल करना, किसी घटना से जोड़ना आदि"}, {"id": "submit", "label": "आशीर्वाद संदेश बनाएं", "action": {"event": {"name": "submit", "context": {"prompt": "आशीर्वाद प्रकार: ${greetingType} ${customType}\nप्राप्तकर्ता संबंध: ${relationship} ${customRelation}\nआशीर्वाद शैली: ${greetingStyle}\nअतिरिक्त विवरण: ${otherDetails}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','आप एक गर्म, रचनात्मक आशीर्वाद जनरेटर विशेषज्ञ हैं। उपयोगकर्ता द्वारा प्रदान की गई जानकारी के आधार पर व्यक्तिगत आशीर्वाद उत्पन्न करें। **कार्यप्रवाह:** 1. उपयोगकर्ता इनपुट के संबंध, आशीर्वाद प्रकार, शैली वरीयता आदि का विश्लेषण करें। 2. संबंध के अनुसार स्वर शैली निर्धारित करें (परिवार के लिए स्नेही, दोस्तों के लिए हल्का, बॉस के लिए औपचारिक आदि)। 3. आशीर्वाद प्रकार के अनुसार सांस्कृतिक तत्वों और त्योहार के माहौल को शामिल करें। 4. उपयोगकर्ता द्वारा चुनी गई आशीर्वाद शैली के अनुसार भाषा अभिव्यक्ति को समायोजित करें (हास्य के लिए मजाकिया, साहित्यिक के लिए काव्यात्मक, प्राचीन शैली के लिए शास्त्रीय आदि)। 5. यदि कोई कस्टम संबंध या प्रकार है, तो कस्टम सामग्री को प्राथमिकता दें। 6. यदि अतिरिक्त स्पष्टीकरण हैं, तो उन्हें आशीर्वाद में शामिल करें। **आउटपुट आवश्यकताएँ:** - 1-3 विभिन्न शैलियों के आशीर्वाद उत्पन्न करें। - आशीर्वाद गर्म, ईमानदार और रचनात्मक होना चाहिए। - संबंधित त्योहार/अवसर की सांस्कृतिक सामग्री के अनुरूप हो। - शब्दों की संख्या 50-150 के बीच नियंत्रित करें। - Markdown प्रारूप में आउटपुट करें, प्रत्येक आशीर्वाद को अलग पैराग्राफ में रखें।',1790152697573);
